        self.assertEqual(string_xor('1010101010', '0101010101'), '1111111111')

    def test_string_xor_empty_strings(self):
        self.assertEqual(string_xor('', ''), '')

    def test_string_xor_mismatched_length_shorter_first(self):
        self.assertEqual(string_xor('10', '1010'), '10')

    def test_string_xor_mismatched_length_longer_first(self):
        self.assertEqual(string_xor('1010', '10'), '10')

    def test_string_xor_leading_zeros(self):
        self.assertEqual(string_xor('00001', '00010'), '00011')

    def test_string_xor_trailing_zeros(self):
        self.assertEqual(string_xor('10000', '01000'), '11000')

    def test_string_xor_mixed_pattern(self):
        self.assertEqual(string_xor('110011', '101010'), '011001')

    def test_string_xor_single_difference(self):
        self.assertEqual(string_xor('1111', '1110'), '0001')

    def test_string_xor_complex_pattern(self):
        self.assertEqual(string_xor('1001001', '0110110'), '1111111')

    def test_string_xor_two_character_strings(self):
        self.assertEqual(string_xor('10', '11'), '01')

    def test_string_xor_returns_string_type(self):
        result = string_xor('101', '010')
        self.assertIsInstance(result, str)

