class TestTotalMatch(unittest.TestCase):
    def test_total_match_both_empty_lists(self):
        self.assertEqual(total_match([], []), [])

    def test_total_match_first_list_shorter(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hI', 'Hi']), ['hi', 'admin'])

    def test_total_match_second_list_shorter(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hi', 'hi', 'admin', 'project']), ['hi', 'admin'])

    def test_total_match_equal_char_count_returns_first_list(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hI', 'hi', 'hi']), ['hi', 'admin'])

    def test_total_match_single_char_strings(self):
        self.assertEqual(total_match(['4'], ['1', '2', '3', '4', '5']), ['4'])

    def test_total_match_first_list_empty(self):
        self.assertEqual(total_match([], ['hello']), [])

    def test_total_match_second_list_empty(self):
        self.assertEqual(total_match(['hello'], []), ['hello'])

    def test_total_match_single_element_lists(self):
        self.assertEqual(total_match(['a'], ['bb']), ['a'])

    def test_total_match_single_element_lists_second_shorter(self):
        self.assertEqual(total_match(['ab'], ['c']), ['c'])

    def test_total_match_single_element_lists_equal(self):
        self.assertEqual(total_match(['ab'], ['cd']), ['ab'])

    def test_total_match_long_strings(self):
        self.assertEqual(total_match(['verylongstring'], ['short']), ['short'])

    def test_total_match_many_short_strings_vs_few_long_strings(self):
        self.assertEqual(total_match(['a', 'b', 'c', 'd', 'e'], ['hello']), ['a', 'b', 'c', 'd', 'e'])

    def test_total_match_identical_lists(self):
        self.assertEqual(total_match(['hi', 'there'], ['hi', 'there']), ['hi', 'there'])

    def test_total_match_empty_strings_in_list(self):
        self.assertEqual(total_match(['', '', ''], ['a']), ['', '', ''])

    def test_total_match_mixed_empty_and_nonempty_strings(self):
        self.assertEqual(total_match(['', 'hello'], ['world']), ['', 'hello'])

    def test_total_match_special_characters(self):
        self.assertEqual(total_match(['!@#'], ['$%^&']), ['!@#'])

    def test_total_match_numbers_as_strings(self):
        self.assertEqual(total_match(['123'], ['456789']), ['123'])

    def test_total_match_whitespace_strings(self):
        self.assertEqual(total_match(['   '], ['      ']), ['   '])

    def test_total_match_unicode_characters(self):
        self.assertEqual(total_match(['café'], ['naïve']), ['café'])

    def test_total_match_case_sensitive(self):
        self.assertEqual(total_match(['ABC'], ['abc']), ['ABC'])

    def test_total_match_very_large_lists(self):
        lst1 = ['a'] * 100
        lst2 = ['bb'] * 50
        self.assertEqual(total_match(lst1, lst2), lst2)

    def test_total_match_one_list_much_longer(self):
        self.assertEqual(total_match(['hi'], ['a', 'b', 'c', 'd', 'e', 'f', 'g']), ['hi'])

    def test_total_match_returns_list_not_copy(self):
        lst1 = ['test']
        lst2 = ['longer']
        result = total_match(lst1, lst2)
        self.assertIs(result, lst1)

    def test_total_match_returns_second_list_when_shorter(self):
        lst1 = ['longer']
        lst2 = ['test']
        result = total_match(lst1, lst2)
        self.assertIs(result, lst2)

    def test_total_match_exactly_equal_character_counts(self):
        self.assertEqual(total_match(['ab', 'cd'], ['abcd']), ['ab', 'cd'])

    def test_total_match_newline_characters(self):
        self.assertEqual(total_match(['a\n'], ['b\n\n']), ['a\n'])

    def test_total_match_tab_characters(self):
        self.assertEqual(total_match(['a\t'], ['b\t\t']), ['a\t'])

